INSERT OR IGNORE INTO cms_versions(id,record_id,revision,data,actor,action,created_at) SELECT 'client-20261011-draft-'||id,id,revision,draft,'site-release','before-client-specification-update',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM cms_records WHERE id='product-t-shirt-bag' AND json_extract(draft,'$.product.variants[0].dimensions')='29 × 38 × 10 cm' AND json_extract(draft,'$.product.variants[1].dimensions')='37 × 45 × 12 cm' AND json_extract(draft,'$.product.variants[2].dimensions')='44 × 58 × 14 cm';
--> statement-breakpoint
INSERT OR IGNORE INTO cms_versions(id,record_id,revision,data,actor,action,created_at) SELECT 'client-20261011-published-'||id,id,revision,published,'site-release','before-client-specification-update',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM cms_records WHERE id='product-t-shirt-bag' AND json_extract(published,'$.product.variants[0].dimensions')='29 × 38 × 10 cm' AND json_extract(published,'$.product.variants[1].dimensions')='37 × 45 × 12 cm' AND json_extract(published,'$.product.variants[2].dimensions')='44 × 58 × 14 cm';
--> statement-breakpoint
UPDATE cms_records SET draft=CASE WHEN json_extract(draft,'$.product.variants[0].dimensions')='29 × 38 × 10 cm' AND json_extract(draft,'$.product.variants[1].dimensions')='37 × 45 × 12 cm' AND json_extract(draft,'$.product.variants[2].dimensions')='44 × 58 × 14 cm' THEN json_set(draft,'$.product.variants',json_array(json_set(json_extract(draft,'$.product.variants[0]'),'$.dimensions','31 × 55 × 18 cm')),'$.activeSizes',json('["Small"]')) ELSE draft END,published=CASE WHEN json_extract(published,'$.product.variants[0].dimensions')='29 × 38 × 10 cm' AND json_extract(published,'$.product.variants[1].dimensions')='37 × 45 × 12 cm' AND json_extract(published,'$.product.variants[2].dimensions')='44 × 58 × 14 cm' THEN json_set(published,'$.product.variants',json_array(json_set(json_extract(published,'$.product.variants[0]'),'$.dimensions','31 × 55 × 18 cm')),'$.activeSizes',json('["Small"]')) ELSE published END,revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='product-t-shirt-bag' AND ((json_extract(draft,'$.product.variants[0].dimensions')='29 × 38 × 10 cm' AND json_extract(draft,'$.product.variants[1].dimensions')='37 × 45 × 12 cm' AND json_extract(draft,'$.product.variants[2].dimensions')='44 × 58 × 14 cm') OR (json_extract(published,'$.product.variants[0].dimensions')='29 × 38 × 10 cm' AND json_extract(published,'$.product.variants[1].dimensions')='37 × 45 × 12 cm' AND json_extract(published,'$.product.variants[2].dimensions')='44 × 58 × 14 cm'));
